parameters.jsCode:
// Parse Ollama response and merge with facility record
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const facility = $('Charlotte Facilities Queue').item.json;
  const rawResponse = item.response || '';

  let subject = 'Same-Day Specimen Courier Service for ' + facility.name;
  let body = rawResponse;

  const subjectMatch = rawResponse.match(/Subject:\s*(.+)/i);
  if (subjectMatch) {
    subject = subjectMatch[1].trim();
    body = rawResponse.replace(/Subject:\s*.+\n+/i, '').trim();
  }

  results.push({
    json: {
      facility_id: facility.id,
      facility_name: facility.name,
      facility_type: facility.facility_type,
      address: facility.address,
      recipient_name: facility.decision_maker_name,
      recipient_title: facility.decision_maker_title,
      recipient_email: facility.contact_email,
      recipient_phone: facility.contact_phone,
      subject: subject,
      email_body: body,
      expected_revenue: 85.0,
      campaign: 'WF-LT005-ACQUIRE',
      dispatched_at: new Date().toISOString(),
      model_used: 'qwen2.5-coder:14b',
      inference_cost_usd: 0.0
    }
  });
}

return results;
